b0088-acac-47e9-96f2-ea117dcad8f1","teacher_id":null,"subject_id":"0764ca66-a5ab-4a93-885b-31a8274a9679","institution_subject_id":"ed878cbb-ee8d-46fb-97a7-832ead4050ae","is_active":true},{"id":"00357e8a-f4e4-5c33-84d0-adeb8c416021","institution_id":"ee34ab2a-8033-4e0b-acf0-05979cce1697","progression_id":"08d30a60-b25c-59c3-a460-296be3a9c4b4","class_id":"654b3f5e-a9f3-4b9b-b285-39b422fe9212","teacher_id":null,"subject_id":"0764ca66-a5ab-4a93-885b-31a8274a9679","institution_subject_id":"ed878cbb-ee8d-46fb-97a7-832ead4050ae","is_active":true},{"id":"46e56e9d-b1f2-5385-9ee1-e42666c36821","institution_id":"ee34ab2a-8033-4e0b-acf0-05979cce1697","progression_id":"4b71b463-6b7c-5efa-b4a2-2ace7cfe96ee","class_id":"f7d28f0d-ff55-4946-ad60-3c80381f2c61","teacher_id":null,"subject_id":"0764ca66-a5ab-4a93-885b-31a8274a9679","institution_subject_id":"ed878cbb-ee8d-46fb-97a7-832ead4050ae","is_active":true},{"id":"2d05e91a-f981-5cc1-a043-897d4b7f0183","institution_id":"ee34ab2a-8033-4e0b-acf0-05979cce1697","progression_id":"bbc0a5ae-82a5-53cb-9f07-6d475261ce34","class_id":"93160f2a-f967-400d-a7ee-eadd385f9f62","teacher_id":null,"subject_id":"0764ca66-a5ab-4a93-885b-31a8274a9679","institution_subject_id":"ed878cbb-ee8d-46fb-97a7-832ead4050ae","is_active":true},{"id":"d38ee19d-58ad-5f5d-8349-d8894cbc7994","institution_id":"ee34ab2a-8033-4e0b-acf0-05979cce1697","progression_id":"bbc0a5ae-82a5-53cb-9f07-6d475261ce34","class_id":"2e7f8b72-efbd-4b31-a0dd-26f055f93497","teacher_id":null,"subject_id":"0764ca66-a5ab-4a93-885b-31a8274a9679","institution_subject_id":"ed878cbb-ee8d-46fb-97a7-832ead4050ae","is_active":true},{"id":"25d18755-a271-51a5-a2d9-9aee00b7971e","institution_id":"ee34ab2a-8033-4e0b-acf0-05979cce1697","progression_id":"fd8f1b68-bc08-5c14-a80f-011b6516dab7","class_id":"bfe85de4-63ff-41f7-af75-b4ec5eb76389","teacher_id":null,"subject_id":"0764ca66-a5ab-4a93-885b-31a8274a9679","institution_subject_id":"ed878cbb-ee8d-46fb-97a7-832ead4050ae","is_active":true},{"id":"b75ab8a5-26c8-5774-a0b8-a936be40126e","institution_id":"ee34ab2a-8033-4e0b-acf0-05979cce1697","progression_id":"1ca955dc-6c82-5e10-beba-509d3e4c0aad","class_id":"7042ee62-feb5-4917-85e3-c5b4869fd81b","teacher_id":null,"subject_id":"0764ca66-a5ab-4a93-885b-31a8274a9679","institution_subject_id":"ed878cbb-ee8d-46fb-97a7-832ead4050ae","is_active":true},{"id":"46f60ab1-ae9c-5c92-8801-c6e7674f73bb","institution_id":"ee34ab2a-8033-4e0b-acf0-05979cce1697","progression_id":"1ca955dc-6c82-5e10-beba-509d3e4c0aad","class_id":"d026e137-20d9-453f-93c8-4bd83c69be8c","teacher_id":null,"subject_id":"0764ca66-a5ab-4a93-885b-31a8274a9679","institution_subject_id":"ed878cbb-ee8d-46fb-97a7-832ead4050ae","is_active":true}]}$data$::jsonb;
  expected_templates integer := jsonb_array_length(payload->'templates');
  expected_items integer := jsonb_array_length(payload->'items');
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.institutions WHERE id='ee34ab2a-8033-4e0b-acf0-05979cce1697' AND name='COURS SECONDAIRE CATHOLIQUE ABOISSO')
    OR NOT EXISTS (SELECT 1 FROM public.institution_subjects WHERE id='ed878cbb-ee8d-46fb-97a7-832ead4050ae' AND institution_id='ee34ab2a-8033-4e0b-acf0-05979cce1697' AND subject_id='0764ca66-a5ab-4a93-885b-31a8274a9679' AND is_active)
  THEN RAISE EXCEPTION 'Établissement ou matière Anglais non conforme'; END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(payload->'assignments') AS a(class_id uuid)
    LEFT JOIN public.classes c ON c.id=a.class_id
    WHERE c.id IS NULL OR c.institution_id <> 'ee34ab2a-8033-4e0b-acf0-05979cce1697' OR c.academic_year <> '2026-2027'
      OR NOT EXISTS (SELECT 1 FROM public.class_teachers ct WHERE ct.class_id=c.id AND ct.institution_id=c.institution_id AND ct.end_date IS NULL AND ct.subject_id IN ('ed878cbb-ee8d-46fb-97a7-832ead4050ae','0764ca66-a5ab-4a93-885b-31a8274a9679'))
  ) THEN RAISE EXCEPTION 'Une classe ou affectation pédagogique ne correspond plus au précontrôle'; END IF;

  IF EXISTS (SELECT 1 FROM public.textbook_progression_templates t WHERE t.academic_year='2026-2027' AND t.subject_name ILIKE '%anglais%' AND t.scope='school' AND t.institution_id='ee34ab2a-8033-4e0b-acf0-05979cce1697' AND t.status <> 'archived' AND coalesce(t.source_metadata->>'seed','') <> 'anglais_dpfc_2026_2027_v1')
  THEN RAISE EXCEPTION 'Une progression Anglais CSCA existe déjà; import interrompu pour éviter un doublon'; END IF;

  INSERT INTO public.textbook_progression_documents
    (id,institution_id,academic_year,original_name,storage_bucket,storage_path,mime_type,size_bytes)
  SELECT id,institution_id,academic_year,original_name,storage_bucket,storage_path,mime_type,size_bytes
  FROM jsonb_to_record(payload->'document') AS x
    (id uuid,institution_id uuid,academic_year text,original_name text,storage_bucket text,storage_path text,mime_type text,size_bytes bigint)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.textbook_progression_templates
    (id,institution_id,academic_year,document_id,subject_id,institution_subject_id,subject_name,level,series,title,description,status,scope,source_national_template_id,is_customized,education_type,source_metadata,published_at)
  SELECT id,institution_id,academic_year,document_id,subject_id,institution_subject_id,subject_name,level,series,title,description,status,scope,source_national_template_id,is_customized,education_type,source_metadata,
    CASE WHEN scope='national' THEN CURRENT_TIMESTAMP ELSE NULL END
  FROM jsonb_to_recordset(payload->'templates') AS x
    (id uuid,institution_id uuid,academic_year text,document_id uuid,subject_id uuid,institution_subject_id uuid,subject_name text,level text,series text,title text,description text,status text,scope text,source_national_template_id uuid,is_customized boolean,education_type text,source_metadata jsonb)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.textbook_progression_items
    (id,institution_id,progression_id,parent_id,item_type,title,description,rubric,theme,competency,trimester,month_label,week_label,planned_duration_minutes,planned_sessions_count,sort_order,indent_level,metadata,source_national_item_id,is_customized)
  SELECT id,institution_id,progression_id,parent_id,item_type,title,description,rubric,theme,competency,trimester,month_label,week_label,planned_duration_minutes,planned_sessions_count,sort_order,indent_level,metadata,source_national_item_id,is_customized
  FROM jsonb_to_recordset(payload->'items') AS x
    (id uuid,institution_id uuid,progression_id uuid,parent_id uuid,item_type text,title text,description text,rubric text,theme text,competency text,trimester text,month_label text,week_label text,planned_duration_minutes integer,planned_sessions_count integer,sort_order integer,indent_level integer,metadata jsonb,source_national_item_id uuid,is_customized boolean)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.textbook_progression_class_assignments
    (id,institution_id,progression_id,class_id,teacher_id,subject_id,institution_subject_id,is_active)
  SELECT id,institution_id,progression_id,class_id,teacher_id,subject_id,institution_subject_id,is_active
  FROM jsonb_to_recordset(payload->'assignments') AS x
    (id uuid,institution_id uuid,progression_id uuid,class_id uuid,teacher_id uuid,subject_id uuid,institution_subject_id uuid,is_active boolean)
  ON CONFLICT (progression_id,class_id,teacher_id_key) DO NOTHING;

  IF NOT EXISTS (SELECT 1 FROM public.textbook_progression_documents WHERE id=(payload->'document'->>'id')::uuid AND storage_path=payload->'document'->>'storage_path')
    OR (SELECT count(*) FROM public.textbook_progression_templates WHERE id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(payload->'templates') AS x) AND source_metadata->>'seed'='anglais_dpfc_2026_2027_v1' AND document_id=(payload->'document'->>'id')::uuid) <> expected_templates
    OR (SELECT count(*) FROM public.textbook_progression_items WHERE id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(payload->'items') AS x) AND metadata->>'seed'='anglais_dpfc_2026_2027_v1') <> expected_items
    OR (SELECT count(*) FROM public.textbook_progression_class_assignments a JOIN jsonb_to_recordset(payload->'assignments') AS x(progression_id uuid,class_id uuid) ON a.progression_id=x.progression_id AND a.class_id=x.class_id WHERE a.is_active AND a.teacher_id IS NULL) <> 9
  THEN RAISE EXCEPTION 'Vérification de l’import échouée; transaction annulée'; END IF;
END;
$import$;
COMMIT;
SELECT scope, count(*) AS progressions FROM public.textbook_progression_templates WHERE source_metadata->>'seed'='anglais_dpfc_2026_2027_v1' GROUP BY scope ORDER BY scope;
